# Function to check the divisibility of m^2 - n^2 for different values of m and n
def find_largest_divisor(limit):
    # List to store the results of m^2 - n^2
    results = []
    # Check all pairs of odd numbers m and n with n < m up to the limit
    for m in range(1, limit, 2):
        for n in range(1, m, 2):
            results.append(m**2 - n**2)
    # Find the GCD of all the results
    return reduce(gcd, results)

