# Function to compute m^2 - n^2 and check divisibility
def check_divisibility():
    results = []
    for m in range(1, 20, 2):
        for n in range(1, m, 2):
            value = m**2 - n**2
            if value % 16 == 0:
                continue
            if value % 8 == 0:
                continue
            if value % 6 == 0:
                continue
            if value % 4 == 0:
                continue
            results.append(value)
    return results

